// GENERATED by the Captain.Food codegen from specs/screens/*.yaml (#/screens) — do not edit
// by hand. The SDUI SCREEN TREES (#87, ADR-0033): one module per surface, each screen's route,
// roles, resolver bindings and component tree as static data. The renderer walks these trees and
// dispatches on `ComponentKind`; `sdui: false` screens carry an EMPTY tree (their markup is
// hand-written — checkout.rs / tracking.rs) but still register their route for the router.

use super::data_layer::ResolverKey;
use super::registry::ComponentKind;

/// One flattened prop on a screen node: literal text, a translation key (resolve via the i18n
/// catalog), or a `{{ path }}` binding into the screen's resolved resolver data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PropValue {
    Text(&'static str),
    I18n(&'static str),
    Binding(&'static str),
}

/// One renderable node of a screen tree.
#[derive(Debug, Clone, Copy)]
pub struct Node {
    pub kind: ComponentKind,
    /// Dotted-path props flattened from the DSL (`empty_state.title`, `action.type`, …).
    pub props: &'static [(&'static str, PropValue)],
    pub children: &'static [Node],
    /// Named branch child groups (#725): `conditional_section`'s `if_true`/`if_false`, verbatim
    /// from the DSL. The renderer evaluates the node's `condition:` prop and renders EXACTLY ONE
    /// group (unevaluatable → neither, fail closed); the condition-defect walk traverses all.
    pub branches: &'static [(&'static str, &'static [Node])],
}

/// One bottom sheet of a surface (#94): the DSL `bottom_sheets` entry as a renderable tree — the
/// renderer mounts every sheet HIDDEN into each of the surface's screens; `open_bottom_sheet`
/// toggles them by id.
#[derive(Debug, Clone, Copy)]
pub struct Sheet {
    pub id: &'static str,
    pub node: Node,
}

/// One screen of a surface.
#[derive(Debug, Clone, Copy)]
pub struct Screen {
    pub id: &'static str,
    pub route: &'static str,
    /// UserType tokens (scalars.yaml#/UserType) admitted to this screen.
    pub roles: &'static [&'static str],
    pub requires_auth: bool,
    /// False = deliberately NOT SDUI-rendered (hand-written page); tree is empty.
    pub sdui: bool,
    pub data_requirements: &'static [ResolverKey],
    /// The GENERATED skip table (#745, §25b): the subset of `data_requirements` PROVEN
    /// structurally unfulfillable at paint time (a required query arg with no route-param, pin
    /// or tenant-host source — each declared on the binding in the DSL). The paint loops skip
    /// these BEFORE any network: the read would fail GraphQL validation on every paint and is
    /// skipped by design, never counted as a degraded render.
    pub skipped_reads: &'static [ResolverKey],
    /// R1 (#639 part C step 2c-ii, PROP-20260831-180622 §5): the UserType token whose
    /// `/{role}/graphql` path THIS screen's transports address, when the DSL declares
    /// `graphql_role:`; `None` = the surface's own role (`Surface::role`, the default every
    /// pre-R1 screen keeps byte-identically). Validator §26 proves every operation the screen
    /// binds admits it, so a declared role can never be a role-refused transport.
    pub graphql_role: Option<&'static str>,
    /// The route a `requires_auth` screen bounces to when the surface has NO session
    /// (`unauthenticated: { type: navigate, route }`, #639 2c-ii): the server 302s a
    /// cookie-less document GET there, the client navigates there on a 401 from its role path.
    /// `None` = the pre-2c-ii behaviour (customer surfaces: the auth sheet over the screen).
    pub unauthenticated_route: Option<&'static str>,
    /// The route a rider bounces to on a REFUSED read/Tell carrying `extensions.reason ==
    /// RIDER_RESTRICTED` (`restricted: { type: navigate, route }`, #639 part C step 4-ii,
    /// ADR-20260904-124600 §2) — the `unauthenticated:` twin, keyed on the server's own standing
    /// signal instead of a missing session. `None` on every screen that declares no bounce (the
    /// `/restricted` screen itself carries none — validator rule `screen-restricted-route-unknown`).
    pub restricted_route: Option<&'static str>,
    /// True on a screen a RESTRICTED rider may still reach without bouncing (`while_restricted:
    /// true`, #639 4-ii): the `/restricted` screen itself. Validator rule
    /// `screen-restricted-binds-uncarved-op` proves such a screen binds only `whileRestricted:`
    /// operations for its role and never mounts `rider_topbar`.
    pub while_restricted: bool,
    pub tree: &'static [Node],
}

impl Node {
    /// The first value of a dotted prop path, if present.
    pub fn prop(&self, key: &str) -> Option<PropValue> {
        self.props.iter().find(|(k, _)| *k == key).map(|(_, v)| *v)
    }

    /// The named branch child group (`if_true`/`if_false`), if this node carries it (#725).
    pub fn branch(&self, name: &str) -> Option<&'static [Node]> {
        self.branches.iter().find(|(n, _)| *n == name).map(|(_, c)| *c)
    }
}

